// Landing page live data.
//
// Everything drawn here comes from this node's own endpoints, and there is
// deliberately very little of it: the page is an overview, so it shows the
// four headline numbers, the live Gini, and the countdown to the next equal
// split. The Lorenz curve, the wealth-cap arithmetic and the fair-share
// figure used to be rendered here too — they now live on /index/score and
// /network, where there is room to explain them instead of merely printing
// them. Nothing here is illustrative: if a number cannot be loaded it stays
// an em dash rather than becoming a plausible-looking placeholder.
//
// This page also carries its own translation table. It is a separate document
// from the explorer, served by a different handler, and explorer.js is 570 KB
// of block-explorer logic that has no business loading here — so the ~50
// strings this page actually shows live below rather than being imported.
// Both readers agree on one thing that matters: the chosen language is stored
// under the same key, so switching on either side carries over to the other.
//
// Phase 0 redesign (2026-09): honest claims, phase badge/disclaimer, and a
// refreshed visual system. Forbidden absolute claims (zero gas, face-vs-all,
// fully open source, zero Sybil, etc.) are removed.
//
// Phase 1 (13.09.2026): the face check is the binding gate again (proof server
// BIO_ATTESTATION_MODE=required). The texts name the limits -- accounts from
// before 25.08.2026 without a face template, uncalibrated threshold,
// head-turn liveness, MPC in shadow -- instead of claiming face-vs-all.

