  "sybil-blurb": "<strong>Sybil / protection:</strong> live face check by two independent matching services that must both agree + two signed attestations + on-chain nullifier, spent once. Named limits: accounts from before 25 Aug 2026 are covered only once their owner adds the face in the app; the matching threshold is not yet calibrated on real captures; only the glance task is binding for liveness, so advanced deepfakes remain a residual risk; each service holds the whole 64-byte sketch, the split mode (<code>MPC</code>) is not yet authoritative. Long term, Aequitas will rely on iris scans to truly guarantee one person, one registration. How that can be implemented reliably and privacy-preserving is being worked on now; hardware and timing are not decided yet.",
