  "disc-body": "Beta: since 25 Aug 2026 the proof server refuses any registration without the signed attestations of the two matching services — a second phone no longer gives the same face a second account. What is not yet true: accounts registered before that date are only covered once their owner adds the face in the app (no new grant); until then they could in principle register again on a new wallet. Error rates are not calibrated (that needs ~1,000 impostor pairs). Liveness: only the glance task is binding today; colour flashes, pulse and parallax are measured but do not decide yet. Read “one human, one account” as “checked, with named limits” — not as “impossible to circumvent.” Long term, Aequitas will rely on iris scans to truly guarantee one person, one registration. How that can be implemented reliably and privacy-preserving is being worked on now; hardware and timing are not decided yet.",
  "beta-why": "<strong>What the beta is for:</strong> it tests whether a person can be recognised again without anyone keeping their picture or a whole face template. The photo and the full face description are deleted within seconds; each of the two matching services keeps only a 64-byte sketch (512 yes/no values) from which the face cannot be reconstructed, but which still recognises a second registration by the same person. This is the groundwork for the iris scan, which is meant to work on the same principle. <strong>Where it stands today:</strong> each service still holds the whole sketch; splitting it so that no service holds it whole is built and tested but not yet active, and error rates are not yet calibrated.",
