  "ex-clara-p": "She spends 3,000 AEQ a month and exchanges 5,000 AEQ. Transfers: 2,000 × 0.1 % = 2 AEQ. Idle money: 15,000 × 0.5 % = 75 AEQ. Exchange: 2,000 × 2 % = 40 AEQ (the first 3,000 are free). All of it goes to the basic income, so also to Anna and Ben.",
