  "jn-sub": "Lo que necesita una panadería, un café o un taller para aceptar AEQ.",
  "jn-1-h": "Abra una cuenta de empresa",
  "jn-1-p": "Una persona verificada y la cartera de la empresa firman juntas. Hasta 10 responsables por empresa y como máximo 3 empresas por persona. Sin registro ni intermediarios.",
  "jn-3-h": "Hágalo circular",
  "jn-3-p": "Los salarios a personas no cuestan nada; los pagos a proveedores, 0,1 %. Hasta mes y medio de facturación nunca paga gravamen.",
  "bx-label": "Costes",
