  "fl-2-h": "0 % de comisión de tarjeta",
  "fl-2-p": "para cada comercio",
  "bc-h": "Lo que cuesta al comercio un pago de 100 €",
  "bc-card": "Pago con tarjeta (típico)",
  "bc-card-v": "0,30–1,50 €",
  "bc-online": "Servicio de pago en línea (típico)",
  "bc-online-v": "2,50–3,00 €",
  "bc-aeq-v": "0,00 €",
  "bc-note": "Comisiones típicas para comercios en Europa. En Aequitas el cliente añade la comisión del 0,1 %, así que el comercio recibe el precio completo. Cambiar AEQ a euros cuesta a las empresas un 2 %, salvo lo que ellas mismas ingresaron.",
  "cf-h": "Adónde van los 3.000 AEQ mensuales de un café",
  "cf-l1": "Salarios 1.500 · sin comisión",
