  "pr-label": "El problema",
  "pr-h2": "El dinero de hoy no es justo",
  "pr-sub": "El dinero nuevo lo crean los bancos y los bancos centrales, y llega primero a quienes ya están cerca. Los demás lo pagan con la inflación o quedan completamente fuera.",
