  "vg-h2": "Dinero que pertenece a las personas, no a quien lo imprime",
  "vg-sub": "Aequitas invierte las reglas. El dinero se crea solo porque existe una persona, y se reparte por igual.",
  "vg-old": "El dinero hoy",
  "vg-q1": "¿Quién crea el dinero?",
  "vg-o1": "Los bancos y bancos centrales, como crédito",
  "vg-n1": "Cada persona verificada recibe 1.000 AEQ. Nadie más crea dinero.",
  "vg-q2": "¿Cuánto dinero hay?",
  "vg-o2": "Cada vez más, decidido por unos pocos",
  "vg-n2": "Siempre exactamente personas × 1.000 AEQ",
  "vg-q3": "¿Quién recibe primero el dinero nuevo?",
  "vg-o3": "Quien ya tiene acceso al crédito",
  "vg-n3": "Cada persona nueva, la misma cantidad",
  "vg-q4": "¿Quién puede participar?",
  "vg-o4": "Quien consigue una cuenta bancaria",
