  "biz-b2-h": "Зарплата без комиссий",
  "biz-b2-p": "Зарплаты в AEQ ничего не стоят. Каждый человек может обменять до 3 000 AEQ в месяц на евро или доллары без сбора.",
  "biz-b3-h": "Без потолка роста",
  "biz-b3-p": "Люди могут держать не более 25 000 AEQ, у бизнеса нет фиксированного предела. До полутора месячных оборотов никогда ничего не стоят.",
  "biz-b4-h": "Оплата за секунды",
  "biz-b4-p": "Деньги приходят за секунды. Без возвратов платежей и ожидания расчётов.",
  "biz-r1-k": "Лежащие деньги",
  "biz-r1-v": "До 1,5 месячного оборота (не меньше 2 000 AEQ): бесплатно · до 3 месячных оборотов: 0,5 % в месяц на превышение · выше: 2 % в месяц · первые полгода: никогда больше, чем заплатил бы человек (до 25 000 AEQ)",
  "biz-r2-k": "Что считается оборотом",
  "biz-r2-v": "Среднее за последние 90 дней или за последние 12 месяцев, если оно выше (для сезонного бизнеса). Покупки учитываются до 9 000 AEQ на человека в квартал; между компаниями учитывается только превышение; зарплаты, собственные взносы и обмен в AEQ не учитываются.",
  "biz-r3-k": "Выход в евро или доллары",
  "biz-r3-v": "Сбор 2 %. То, что вы сами обменяли на AEQ, возвращается без сбора. Люди: дополнительно 3 000 AEQ в месяц бесплатно",
  "biz-r4-k": "Между компаниями",
