  "eco-p1-h": "钱只为人而创造",
  "eco-p1-p": "每位已验证的个人一次性获得 1,000 AEQ。其他人都不能创造货币：企业、验证者、创始人都不行。",
  "eco-p2-h": "流通受到奖励",
