  "ppl-label": "对个人",
  "ppl-h2": "对每个人的六项承诺",
  "ppl-sub": "最公平的货币，首先要让拥有很少的人感到公平。",
  "ppl-1": "<strong>你的公平份额不可触碰。</strong>前 1,000 AEQ 永不征收任何费用。",
  "ppl-2": "<strong>日常生活不花钱。</strong>每月花费的前 1,000 AEQ 免手续费。",
  "ppl-3": "<strong>工资就是工资。</strong> 每月最多 3,000 AEQ 可免税兑换成欧元或美元，不论钱从何而来。",
  "ppl-4": "<strong>允许储蓄。</strong>5,000 AEQ 以内的储蓄不受任何损失。",
  "ppl-5": "<strong>多者多担。</strong> 储蓄超过 5,000 AEQ 的部分每月支付 0.5 %；25,000 AEQ 的上限不变。",
  "ppl-6": "<strong>个人在持有和退出方面支付的费用始终低于企业，</strong>而任何人支付的一切都会平均回到所有人手中。",
