  "pr-1": "自 2001 年以来，欧元货币供应量（M2）增长了三倍多：从不到 4.6 万亿欧元增至约 15.1 万亿欧元。",
  "pr-2": "的全球个人财富属于最富有的 10%。较贫穷的一半人类仅拥有约 2%。",
  "pr-3-v": "13 亿",
  "pr-3": "全球成年人没有账户，被排除在现代货币之外。",
  "pr-src": "来源：欧洲央行/Statista（M2 2001–2023）、世界不平等报告、世界银行 Global Findex 2025。",
  "vg-label": "变革",
  "vg-h2": "属于人民的货币，而不属于印钞者",
  "vg-sub": "Aequitas 颠覆了规则。货币只因一个人的存在而产生，并且平均分配。",
