  "vg-q5": "手续费流向哪里？",
  "vg-o5": "给银行和支付公司",
  "vg-n5": "100% 作为基本收入回到每个人手中",
  "vg-q6": "囤积的钱会怎样？",
  "vg-o6": "巨额财富持续增长",
  "vg-n6": "闲置的钱会流回每个人",
  "fn-label": "货币必须做到什么",
  "fn-h2": "货币的三大职能，公平地实现",
  "fn-sub": "任何货币都必须做到三件事。Aequitas 三者兼备，并且对每个人一视同仁。",
  "fn-1-h": "支付手段",
  "fn-1-p": "在世界任何地方几秒钟完成支付，没有刷卡费。每月前 1,000 AEQ 的消费免手续费，商家收到全额价款。",
  "fn-2-h": "价值储藏",
  "fn-2-p": "新钱只随新的人产生，每人 1,000 AEQ——因此人均始终正好是 1,000 AEQ，谁也无法稀释。5,000 AEQ 以内的储蓄不收取任何费用。",
  "fn-3-h": "计价单位",
  "fn-3-p": "一个公平份额始终是 1,000 AEQ：即普通人所持有的数额。每条规则都是它的倍数，在任何国家都易于理解。",
  "mg-label": "没有印钞带来的通胀",
  "mg-h2": "货币总量 = 人数 × 1,000",
  "mg-sub": "任何政府、任何央行，甚至创始人都无法创造 AEQ。只有新的人加入时才会产生新货币，且正好 1,000 AEQ。您在全部货币中的份额保持不变。",
  "mg-1": "<strong>1 人 = 1,000 AEQ。</strong>起步时没有人多得。",
  "mg-2": "<strong>规则是公开的。</strong>它们写在公开的源代码中，对所有人一视同仁。",
  "mg-3": "<strong>实时测量。</strong>货币总量和不平等程度随时可在链上查看。",
  "mg-c-h": "货币有多少",
  "mg-c-eur": "欧元（M2）",
  "mg-c-e1": "4.6 万亿 €",
  "mg-c-e2": "15.1 万亿 €",
  "mg-p-v": "1,000",
  "mg-c-aeq": "每人，始终如此",
  "mg-c-note": "欧元：欧元区的货币总量。Aequitas：总量只随人数增长，因此每个人的份额始终是 1,000 AEQ。",
  "ul-label": "流通激励",
  "ul-h2": "钱应该流动，而不是闲置",
  "ul-sub": "持有远超公平份额的人，需对超出部分每月缴纳一笔小额费用。它永远不会消失：每一个 AEQ 都作为基本收入回到所有人手中。这样钱保持流动，财富也无法无限累积。",
  "ul-1": "<strong>您的前 5,000 AEQ 不可触碰。</strong>这是公平份额的五倍。",
  "ul-2": "<strong>超出部分每月 0.5%</strong>（个人）。企业 1.5 个月营业额以内免费。",
  "ul-3": "<strong>经过历史检验。</strong>1932 年在奥地利沃格尔，带有流通费的货币在大萧条中修建了道路和桥梁。",
  "calc-h": "试一试：您需要支付多少？",
  "calc-l-bal": "您的余额",
  "calc-free": "免费",
  "calc-over": "每月 0.5%",
  "calc-l-fee": "每月费用",
  "calc-note": "所缴纳的一切都作为基本收入回到所有人手中，也包括您。",
  "vi-label": "愿景",
  "vi-h2": "如果 80 亿人都参与",
  "vi-sub": "一种在全世界平等属于每个人的货币。不是靠强制再分配，而是靠从一开始就对每个人都相同的规则。",
  "vi-1-v": "80 亿",
  "vi-1": "人，每人拥有同样的 1,000 AEQ 公平份额",
  "vi-2-v": "0",
  "vi-2": "能多印钞的政府或银行",
  "vi-3": "的每一笔手续费和费用每天回到所有人手中",
  "nav-why": "为什么是 Aequitas",
  "nav-join": "加入",
  "nav-trans": "透明",
  "pz-label": "原则",
  "pz-h2": "货币本应如此简单",
  "pz-sub": "三条规则，对地球上每个人都一样。",
  "pz-1-h": "一人一户",
  "pz-1-p": "每个人只能注册一次。只有真实的人：没有机器人，没有重复。",
  "pz-2-h": "每人 1,000 AEQ",
  "pz-2-p": "每个人获得同样的公平份额。除此之外，永远不会创造新的货币。",
  "pz-3-h": "每天都有基本收入",
  "pz-3-p": "手续费和各项费用每天平均回流给所有人。",
  "pz-link": "详细了解运作方式 →",
  "wy-label": "为什么世界需要它",
  "wy-h2": "为什么将会需要 Aequitas",
  "wy-sub": "这不是一时的想法，而是对世界发展方向的回答。世界变化越大，就越需要属于人民的货币。",
  "wy-1-h": "机器接管工作",
  "wy-1-p": "人工智能和自动化承担的工作越来越多。不依赖工作岗位的收入变得不可或缺。Aequitas 每天向每个人支付基本收入，资金来自货币流通，而不是税收，也不是印钞。",
  "wy-2-h": "作为人变得珍贵",
  "wy-2-p": "在充斥着机器人和 AI 伪造的世界里，证明某人是真实的人变得弥足珍贵。Aequitas 正是建立在这一点上：一人一户。",
  "wy-3-h": "不平等持续扩大",
  "wy-3-p": "自 1990 年代以来，最大的财富增长速度约为较贫穷一半人类财富增速的两倍。Aequitas 内置了刹车：囤积需要付费，一切都回流给所有人。",
  "wy-4-h": "数十亿人被排除在外",
  "wy-4-p": "全球有 13 亿成年人没有账户。使用 Aequitas，一部智能手机就够了。",
  "wy-5-h": "值得信赖的货币",
  "wy-5-p": "政府和央行可以随时决定创造货币。Aequitas 的规则是公开的，对所有人都一样，没有人能多印。",
  "wy-6-h": "服务于人的货币",
  "wy-6-p": "钱应该流向人们生活和工作的地方，而不是堆积起来。流通让本地商家和社区保持活力。",
  "wy-link": "Aequitas 背后的完整理念 →",
  "zg-label": "人人可用",
  "zg-h2": "人人都能使用",
  "zg-sub": "Aequitas 属于地球上的每一个人，无论国家、收入或银行。",
  "zg-1-h": "一部智能手机就够了",
  "zg-1-p": "通过简短的实时人脸核验即可注册。无需银行账户，无需繁琐手续。",
  "zg-2-h": "长期方向：虹膜扫描",
  "zg-2-p": "从长远看，虹膜扫描将确保“一人一次注册”，即使在数十亿人之中。正在研发中；硬件和时间表尚未确定。",
  "zg-3-h": "无需银行，无需信用审查",
  "zg-3-p": "无需住址、信用评级或最低收入。是人就够了。",
  "zg-4-h": "遍及全球，支持 12 种语言",
  "zg-4-p": "每个国家的每个人适用同样的规则。",
  "zg-note": "照片在几秒内删除。比对服务只保留一份无法还原人脸的 64 字节摘要，链上只存储你是新的一个人的证明，而不是你是谁。",
  "zg-btn": "如何加入 →",
  "gr-label": "Aequitas 为何存在",
  "gr-h2": "由一个人创造，为所有人服务",
  "gr-p1": "Aequitas 不是由银行、企业或投资者创立的。它由一个人发起，怀着一个简单的信念：货币之所以存在，是因为人存在，每个人都应拥有同样的份额。",
  "gr-p2": "因此，也不会为创始人创造任何货币。和其他人一样，创始人作为已验证者获得 1,000 AEQ。源代码是公开的，任何人都可以核实规则对所有人都一样。",
  "gr-sig": "Aequitas 创始人",
  "tw-label": "实时且公开",
  "tw-h2": "一切都可见",
  "tw-sub": "每个区块、每个账户和每条规则，任何人随时都可以核查。",
  "tw-ex-h": "区块浏览器",
  "tw-ex-p": "每个区块、每笔转账、每个账户。",
  "tw-eq-h": "平等指数",
  "tw-eq-p": "基尼系数和洛伦兹曲线，实时来自链上。",
  "tw-nw-h": "网络",
  "tw-nw-p": "活跃节点以及区块的产生方式。",
  "tw-xc-h": "兑换",
  "tw-xc-p": "将 AEQ 兑换为测试币 tUSD。",
  "tw-gh-h": "源代码",
  "tw-gh-p": "所有规则均开源。",
  "pg-why-h1": "为什么是 Aequitas",
  "pg-why-sub": "今天的货币哪里出了问题，货币必须做到什么，以及为什么平等属于每个人的货币才是答案。",
  "toc-problem": "问题",
  "toc-fn": "货币的职能",
  "toc-mg": "货币总量",
  "toc-vi": "愿景",
  "pg-join-h1": "加入",
  "pg-join-sub": "三步完成注册，获得 1,000 AEQ，并每天领取基本收入。无需银行账户。",
  "toc-steps": "三个步骤",
  "toc-share": "您的份额",
  "pg-trans-h1": "透明",
  "pg-trans-sub": "来自链上的实时数据、开放工具、Aequitas 的现状，以及坦白说仍待解决的问题。",
