  "nav-equality": "平等",
  "nav-exchange": "兑换",
  "rm-6-h": "长期：虹膜扫描",
  "rm-6-p": "为了真正保证“一人一次注册”，Aequitas 长期将依靠虹膜扫描。目前正在研究如何实现；我们不承诺具体日期。",
  "op-6": "<strong>人脸检查只是过渡步骤。</strong>手机上的实时人脸检查让重复注册难得多，但还不能毫无疑问地证明“一人一次注册”。因此我们正在研究虹膜扫描；具体如何实现仍未确定。",
