  "hero-h1": "Uang, karena ada <span>manusia</span>.",
  "hero-sub": "Setiap orang menerima bagian yang sama: 1.000 AEQ. Tak seorang pun bisa mencetak lebih. Tanpa rekening bank, tanpa kartu identitas.",
  "btn-register": "Daftar sekarang",
