  "how-label": "Pendaftaran",
  "how-h2": "Tiga langkah jujur (Beta)",
  "how-sub": "Dompet di ponsel, rekaman wajah langsung yang singkat, dan hibah sekali — tanpa rekening bank.",
  "step1-h": "Pindai",
  "step1-p": "Pasang dompet di ponsel Anda dan lakukan pengambilan wajah langsung yang singkat. Dua layanan independen memeriksa bahwa Anda belum terdaftar. Gambarnya dihapus.",
  "step2-h": "Buktikan",
  "step2-p": "Aplikasi mengirim bukti ke rantai bahwa Anda baru, tanpa mengungkap siapa Anda.",
  "step3-h": "Terima",
  "step3-p": "1.000 AEQ sekali per pendaftaran berhasil.",
  "sybil-blurb": "<strong>Sybil / perlindungan:</strong> pemeriksaan wajah langsung oleh dua layanan pencocokan independen yang keduanya harus setuju + dua atestasi bertanda tangan + nullifier di rantai, sekali pakai. Batas yang disebutkan: akun dari sebelum 25-08-2026 baru tercakup setelah pemiliknya menambahkan wajah di aplikasi; ambang pencocokan belum dikalibrasi dengan tangkapan nyata; untuk deteksi kehidupan hanya tugas lirikan yang mengikat, sehingga deepfake canggih tetap menjadi risiko sisa; setiap layanan memegang cuplikan 64 byte utuh, mode terbagi (<code>MPC</code>) belum menentukan. Dalam jangka panjang, Aequitas akan mengandalkan pemindaian iris untuk benar-benar menjamin satu orang, satu pendaftaran. Cara menerapkannya secara andal dan menjaga privasi sedang dikerjakan saat ini; perangkat keras dan jadwalnya belum ditentukan.",
  "how-link": "Daftar dan ambil 1.000 AEQ Anda →",
  "why-label": "Keadilan",
  "why-h2": "Gini Bitcoin ~0,85 — lebih tinggi daripada negara mana pun",
  "why-sub": "Suplai = manusia terverifikasi × 1.000 AEQ. Gini dari node live. Go L1 adalah sumber kebenaran ledger (bukan hanya kontrak cermin).",
  "why-link": "Kurva Lorenz, riwayat, dan perbandingan antarnegara →",
  "disc-title": "Peringatan beta",
  "disc-body": "Beta: sejak 25-08-2026 server bukti menolak setiap pendaftaran tanpa atestasi bertanda tangan dari kedua layanan pencocokan — ponsel kedua tidak lagi memberi akun kedua untuk wajah yang sama. Yang belum berlaku: akun dari sebelum tanggal itu baru tercakup setelah pemiliknya menambahkan wajah di aplikasi (tanpa hibah baru); sampai saat itu pada prinsipnya mereka bisa mendaftar lagi dengan dompet baru. Laju kesalahan belum dikalibrasi (perlu ~1.000 pasangan impostor). Deteksi kehidupan: saat ini hanya tugas lirikan yang mengikat; kilatan warna, denyut, dan paralaks diukur tetapi belum menentukan. Bacalah “satu manusia, satu akun” sebagai “diperiksa, dengan batas yang disebutkan” — bukan “mustahil dilewati”. Dalam jangka panjang, Aequitas akan mengandalkan pemindaian iris untuk benar-benar menjamin satu orang, satu pendaftaran. Cara menerapkannya secara andal dan menjaga privasi sedang dikerjakan saat ini; perangkat keras dan jadwalnya belum ditentukan.",
  "beta-why": "<strong>Untuk apa beta ini:</strong> menguji apakah seseorang bisa dikenali kembali tanpa ada yang menyimpan fotonya atau templat wajah utuh. Foto dan deskripsi wajah lengkap dihapus dalam beberapa detik; kedua layanan pencocokan masing-masing hanya menyimpan cuplikan 64 byte (512 nilai ya/tidak). Wajah tidak dapat direkonstruksi darinya, tetapi cuplikan itu mengenali pendaftaran kedua oleh orang yang sama. Ini fondasi untuk pemindaian iris, yang dirancang bekerja dengan prinsip yang sama. <strong>Keadaan saat ini:</strong> setiap layanan masih memegang cuplikan utuh; membaginya agar tidak ada layanan yang memegangnya utuh sudah dibangun dan diuji tetapi belum aktif, dan laju kesalahan belum dikalibrasi.",
  "oss-line": "<strong>Sumber terbuka:</strong> Rantai inti publik · layanan identitas/bukti sebagian privat selama beta.",
