  "cmp-v-1k": "1.000 AEQ (1×)",
  "eco-label": "Ekonomi",
  "eco-h2": "Tek döngü, üç rol",
  "eco-sub": "İnsanlar temel geliri alır ve harcar. İşletmeler onu kazanır ve maaş ile alım olarak aktarır. Bekleyen ya da ağdan çıkan para temel gelire geri akar ve oradan herkese eşit olarak dağılır.",
  "eco-svg-people": "İnsanlar",
  "eco-svg-biz": "İşletmeler",
  "eco-svg-ubi": "Temel gelir",
