  "eco-svg-wages": "maaşlar",
  "eco-svg-daily": "her gün, herkese eşit",
  "eco-svg-levies": "bekleyen para · çıkış · ücretler",
  "eco-p1-h": "Para yalnızca insanlar için yaratılır",
  "eco-p1-p": "Doğrulanmış her insan bir kez 1.000 AEQ alır. Başka kimse para yaratmaz: ne işletmeler, ne doğrulayıcılar, ne kurucular.",
  "eco-p2-h": "Dolaşım ödüllendirilir",
  "eco-p2-p": "Alışveriş yapmak, maaş ve tedarikçi ödemek çok az ya da hiç maliyet getirmez. Açık sınırların ötesinde bekleyen para küçük bir aylık kesinti öder.",
  "eco-p3-h": "Her kesinti herkese geri döner",
  "eco-p3-p": "Transfer ücretleri, bekleyen para kesintileri ve çıkış kesintileri %100 temel gelire gider ve her gün doğrulanmış her insana eşit olarak ödenir.",
  "cmp-label": "İnsan mı, işletme mi?",
  "cmp-h2": "Üç hesap türü, tek kural seti",
  "cmp-sub": "Kimse sizin ne olduğunuzu kontrol etmez. Kurallar her türlü istiflemeyi pahalı, parayı aktarmayı ucuz hale getirir; bu yüzden herkes kendine gerçekten uyan hesabı seçer.",
