  "cmp-r6-f": "herkes",
  "cmp-note": "Bu kurallar 26 Eylül 2026'dan itibaren geçerlidir. Her kesinti %100 temel gelire gider.",
  "ppl-label": "İnsanlar için",
  "ppl-h2": "Her insana altı söz",
  "ppl-sub": "En adil para, önce az şeyi olan insana adil hissettirmelidir.",
  "ppl-1": "<strong>Adil payınız dokunulmazdır.</strong> İlk 1.000 AEQ asla kesintiye uğramaz.",
  "ppl-2": "<strong>Günlük hayat hiçbir şeye mal olmaz.</strong> Her ay harcadığınız ilk 1.000 AEQ ücretsizdir.",
  "ppl-3": "<strong>Maaş maaştır.</strong> Paranın nereden geldiğine bakılmaksızın ayda 3.000 AEQ'ya kadar kesintisiz avro veya dolara çevrilir.",
  "ppl-4": "<strong>Birikim yapmak serbesttir.</strong> 5.000 AEQ'ya kadar birikiminiz hiçbir şey kaybetmez.",
  "ppl-5": "<strong>Daha çok olan daha çok katkı yapar.</strong> 5.000 AEQ üzerindeki birikim ayda %0,5 öder; 25.000 AEQ sınırı kalır.",
  "ppl-6": "<strong>İnsanlar tutmak ve çıkmak için her zaman işletmelerden daha az öder,</strong> ve kim ne öderse, tüm insanlara eşit olarak geri döner.",
  "biz-label": "İşletmeler için",
  "biz-h2": "AEQ kabul edin, aktarın, hiçbir şey ödemeyin",
  "biz-sub": "İşletmeler AEQ kabul edebilir, tutabilir ve harcayabilir. Kurallar parayı işletmelerin içinden geçirip insanlara geri akıtır: bekletmek maliyetlidir, aktarmak ücretsizdir.",
  "biz-b1-h": "Kart komisyonu yok",
  "biz-b1-p": "Bir ödeme işletmeye hiçbir şeye mal olmaz. Müşteriler her ay ilk 1.000 AEQ'yu ücretsiz harcar.",
  "biz-b2-h": "Ücretsiz maaş ödemesi",
  "biz-b2-p": "AEQ ile ödenen maaşlar hiçbir şeye mal olmaz. Herkes ayda 3.000 AEQ'ya kadar kesintisiz avro veya dolara çevirebilir.",
  "biz-b3-h": "Büyüme sınırı yok",
  "biz-b3-p": "İnsanlar en fazla 25.000 AEQ tutabilir; işletmelerin sabit bir sınırı yoktur. Bir buçuk aylık ciroya kadar hiçbir zaman maliyet doğmaz.",
  "biz-b4-h": "Saniyeler içinde ödeme",
  "biz-b4-p": "Para saniyeler içinde gelir. Ters ibraz yok, mutabakat beklemek yok.",
  "biz-r1-k": "Bekleyen para",
  "biz-r1-v": "1,5 aylık ciroya kadar (en az 2.000 AEQ): ücretsiz · 3 aylık ciroya kadar: aşan kısım için ayda %0,5 · üstü: ayda %2 · ilk altı ay: asla bir insanın ödeyeceğinden fazla değil (25.000 AEQ'ya kadar)",
  "biz-r2-k": "Ciro olarak ne sayılır",
  "biz-r2-v": "Son 90 günün ortalaması ya da daha yüksekse son 12 ayın ortalaması (mevsimlik işletmeler için). Alışverişler kişi ve çeyrek başına 9.000 AEQ'ya kadar sayılır; işletmeler arasında yalnızca fazla sayılır; ücretler, kendi ödemeleriniz ve AEQ'ya dönüşüm sayılmaz.",
  "biz-r3-k": "Avro veya dolara çıkış",
  "biz-r3-v": "%2 kesinti. Kendiniz AEQ'ya çevirdiğiniz tutar kesintisiz geri döner. İnsanlar: ayrıca ayda 3.000 AEQ ücretsiz",
