  "pr-label": "Sorun",
  "pr-h2": "Bugünün parası adil değil",
  "pr-sub": "Yeni para bankalar ve merkez bankaları tarafından yaratılır ve önce zaten ona yakın olanlara ulaşır. Diğer herkes bunun bedelini enflasyonla öder ya da tamamen dışarıda kalır.",
  "pr-1-v": "×3,3",
  "pr-1": "Avro para arzı (M2) 2001'den bu yana üç katından fazla arttı: 4,6 trilyon avronun altından yaklaşık 15,1 trilyon avroya.",
  "pr-2": "dünyadaki tüm kişisel servetin en zengin %10'a aittir. İnsanlığın yoksul yarısının payı yaklaşık %2'dir.",
  "pr-3-v": "1,3 milyar",
  "pr-3": "yetişkinin dünya genelinde hesabı yok ve modern paradan dışlanmış durumda.",
  "pr-src": "Kaynaklar: AMB/Statista (M2 2001–2023), World Inequality Report, Dünya Bankası Global Findex 2025.",
  "vg-label": "Devrim",
  "vg-h2": "Onu basanlara değil, insanlara ait para",
  "vg-sub": "Aequitas kuralları tersine çevirir. Para yalnızca bir insan var olduğu için doğar ve eşit paylaştırılır.",
  "vg-old": "Bugünün parası",
  "vg-q1": "Parayı kim yaratır?",
  "vg-o1": "Bankalar ve merkez bankaları, kredi olarak",
  "vg-n1": "Doğrulanmış her insan 1.000 AEQ alır. Başka kimse para yaratmaz.",
  "vg-q2": "Ne kadar para var?",
  "vg-o2": "Giderek artar, birkaç kişi karar verir",
  "vg-n2": "Her zaman tam olarak insan sayısı × 1.000 AEQ",
  "vg-q3": "Yeni parayı önce kim alır?",
