  "vg-q4": "Kim katılabilir?",
  "vg-o4": "Banka hesabı alabilen",
  "vg-n4": "Her insan. Banka, kredi kontrolü ya da adres gerekmez.",
  "vg-q5": "Ücretler nereye gider?",
  "vg-o5": "Bankalara ve ödeme şirketlerine",
  "vg-n5": "%100'ü temel gelir olarak herkese geri",
  "vg-q6": "İstiflenen paraya ne olur?",
  "vg-o6": "Büyük servetler büyümeye devam eder",
  "vg-n6": "Bekleyen para herkese geri akar",
  "fn-label": "Paranın yapması gerekenler",
  "fn-h2": "Paranın üç işlevi, adil biçimde",
  "fn-sub": "Her para üç şeyi yapabilmelidir. Aequitas üçünü de yapar ve bunu her insan için eşit yapar.",
  "fn-1-h": "Ödeme aracı",
  "fn-1-p": "Dünyanın her yerinde, saniyeler içinde, kart ücreti olmadan ödeyin. Her ay harcadığınız ilk 1.000 AEQ ücretsizdir ve dükkân tam fiyatı alır.",
  "fn-2-h": "Değer saklama",
  "fn-2-p": "Yeni para yalnızca yeni bir insanla, kişi başı 1.000 AEQ olarak doğar — böylece her zaman kişi başına tam 1.000 AEQ vardır ve kimse bunu sulandıramaz. 5.000 AEQ'ya kadar birikiminiz kesinti ödemez.",
  "fn-3-h": "Hesap birimi",
  "fn-3-p": "Bir adil pay her zaman 1.000 AEQ'dur: ortalama bir insanın tuttuğu kadar. Her kural bunun katıdır ve her ülkede anlaşılır.",
  "mg-label": "Para basımıyla enflasyon yok",
  "mg-h2": "Para arzı = insanlar × 1.000",
  "mg-sub": "Hiçbir hükümet, merkez bankası, hatta kurucular bile AEQ yaratamaz. Yeni para yalnızca yeni bir insan katıldığında ve tam olarak 1.000 AEQ olarak oluşur. Tüm paradaki payınız aynı kalır.",
  "mg-1": "<strong>1 insan = 1.000 AEQ.</strong> Başlangıçta kimse daha fazlasını almaz.",
  "mg-2": "<strong>Kurallar açık.</strong> Herkese açık kaynak kodunda yazılı ve herkes için aynı.",
  "mg-3": "<strong>Canlı ölçülür.</strong> Para arzı ve eşitsizlik zincirde her an görülebilir.",
  "mg-c-h": "Ne kadar para var",
  "mg-c-eur": "Avro (M2)",
  "mg-c-e1": "4,6 trl €",
  "mg-c-e2": "15,1 trl €",
  "mg-p-v": "1.000",
  "mg-c-aeq": "kişi başına, her zaman",
  "mg-c-note": "Avro: avro bölgesindeki para miktarı. Aequitas: miktar yalnızca insan sayısıyla büyür, bu yüzden her insanın payı 1.000 AEQ'da kalır.",
  "ul-label": "Dolaşım teşviki",
  "ul-h2": "Para akmalı, beklememeli",
  "ul-sub": "Adil payın çok üzerinde tutan, aşan kısım için küçük bir aylık kesinti öder. Bu asla kaybolmaz: her AEQ temel gelir olarak tüm insanlara geri döner. Böylece para hareket halinde kalır ve servet sınırsızca birikemez.",
  "ul-1": "<strong>İlk 5.000 AEQ'nuza dokunulmaz.</strong> Bu, adil payın beş katıdır.",
  "ul-2": "<strong>Üstü için ayda %0,5</strong> (insanlar). İşletmeler 1,5 aylık ciroyu ücretsiz tutar.",
  "ul-3": "<strong>Tarihte sınanmış.</strong> Wörgl'de (Avusturya, 1932) dolaşım kesintili para, Büyük Buhran'ın ortasında yollar ve köprüler inşa etti.",
  "calc-h": "Deneyin: ne kadar ödersiniz?",
  "calc-l-bal": "Bakiyeniz",
  "calc-free": "ücretsiz",
  "calc-over": "ayda %0,5",
  "calc-l-fee": "Aylık kesinti",
  "calc-note": "Ödenen her şey temel gelir olarak tüm insanlara, yani size de geri döner.",
  "vi-label": "Vizyon",
  "vi-h2": "8 milyar insan katılırsa",
  "vi-sub": "Dünya çapında herkese eşit ait bir para. Zorla yeniden dağıtımla değil, baştan itibaren her insan için aynı olan kurallarla.",
  "vi-1-v": "8 milyar",
  "vi-1": "insan, her birinin eşit adil payı 1.000 AEQ",
  "vi-2-v": "0",
  "vi-2": "daha fazla basabilecek hükümet ya da banka",
