  "fp-h2": "Votre juste part, chaque jour",
  "fp-sub": "Chaque personne vérifiée reçoit 1 000 AEQ une fois, puis chaque jour une part égale de tout ce que le réseau collecte.",
  "fp-btn": "Les six promesses, le revenu de base et des exemples →",
  "st-h2": "Bêta : un test public",
  "st-p": "Aequitas fonctionne, mais n’est pas terminé. L’AEQ ne s’échange que contre la monnaie de test tUSD, l’examen juridique au titre du règlement crypto de l’UE est encore en attente, et la vérification faciale a des limites connues. Les règles économiques s’appliquent à partir du 26 septembre 2026.",
