  "bc-note": "Frais typiques des commerçants en Europe. Chez Aequitas, le client ajoute les frais de 0,1 %, le commerce reçoit donc le prix complet. Changer des AEQ en euros coûte 2 % aux entreprises, sauf pour ce qu’elles ont versé elles-mêmes.",
