  "ppl-label": "Para as pessoas",
  "ppl-h2": "Seis promessas a cada pessoa",
  "ppl-sub": "O dinheiro mais justo tem de parecer justo primeiro para quem tem pouco.",
  "ppl-1": "<strong>Sua parte justa é intocável.</strong> Os primeiros 1.000 AEQ nunca pagam encargo.",
  "ppl-2": "<strong>O dia a dia não custa nada.</strong> Os primeiros 1.000 AEQ que você gasta por mês são livres de taxa.",
