  "biz-r1-k": "Dinheiro parado",
  "biz-r1-v": "Até 1,5 meses de faturação (mínimo 2.000 AEQ): livre · até 3 meses de faturação: 0,5 % ao mês sobre a parte acima · acima disso: 2 % ao mês · primeiros seis meses: nunca mais do que pagaria uma pessoa (até 25.000 AEQ)",
