  "ubi-label": "Renda básica",
  "ubi-h2": "Todo dia, partes iguais para todos",
  "ubi-sub": "Nenhum dinheiro é criado para a renda básica. Ela é paga só com o que a rede arrecada, e tudo o que é arrecadado é distribuído.",
  "ubi-c1-h": "Início: 1.000 AEQ",
