  "fee-note": "A taxa é somada por cima: quem recebe fica sempre com o valor completo, por isso um preço de 10 AEQ rende à loja exatamente 10 AEQ. Não há sobretaxas para saldos grandes: a riqueza já está limitada pelo teto de 25.000 AEQ e pela taxa sobre poupança acima de 5.000 AEQ. Estas regras valem a partir de 26 de setembro de 2026.",
