  "bc-note": "Taxas típicas para comerciantes na Europa. Na Aequitas o cliente acrescenta a taxa de 0,1 %, pelo que a loja recebe o preço completo. Trocar AEQ por euros custa 2 % às empresas, exceto o que elas próprias depositaram.",
