  "nw-cd-h": "dias até ao início das regras económicas",
  "nw-cd-p": "A partir de 26 de setembro de 2026, empresas, pessoas e outros endereços têm regras próprias. Cada taxa vai para o rendimento básico.",
  "nw-soon": "Em breve",
  "nw-1-d": "26 set. 2026",
