  "cmp-sub": "لا أحد يتحقق مما أنت عليه. القواعد تجعل الاكتناز مكلفًا بكل أشكاله وتمرير المال رخيصًا، لذلك يختار كل واحد الحساب الذي يناسبه حقًا.",
