  "biz-r1-k": "المال الراكد",
  "biz-r1-v": "حتى مبيعات 1.5 شهر (2,000 AEQ على الأقل): مجانًا · حتى مبيعات 3 أشهر: 0.5 % شهريًا على الجزء الزائد · فوق ذلك: 2 % شهريًا · الأشهر الستة الأولى: لا أكثر أبدًا مما يدفعه شخص (حتى 25,000 AEQ)",
  "biz-r2-k": "ما يُحتسب مبيعات",
  "biz-r2-v": "متوسط آخر 90 يومًا، أو آخر 12 شهرًا إن كان أعلى (للأعمال الموسمية). تُحتسب المشتريات حتى 9,000 AEQ لكل شخص في كل ربع سنة؛ وبين الشركات يُحتسب الفائض فقط؛ ولا تُحتسب الأجور ولا مدفوعاتكم الخاصة ولا التحويل إلى AEQ.",
  "biz-r3-k": "الخروج إلى اليورو أو الدولار",
  "biz-r3-v": "رسم 2 %. ما حوّلتموه بأنفسكم إلى AEQ يعود بلا رسم. الأفراد: إضافةً إلى ذلك 3,000 AEQ شهريًا مجانًا",
