  "ubi-label": "الدخل الأساسي",
  "ubi-h2": "كل يوم، حصص متساوية للجميع",
  "ubi-sub": "لا يُنشأ مال من أجل الدخل الأساسي. يُدفع فقط مما تجمعه الشبكة، وكل ما يُجمع يُوزَّع.",
  "ubi-c1-h": "البداية: 1,000 AEQ",
