  "pr-label": "المشكلة",
  "pr-h2": "مال اليوم ليس عادلًا",
  "pr-sub": "تنشئ البنوك والبنوك المركزية المال الجديد، فيصل أولًا إلى من هم قريبون منه أصلًا. أما الباقون فيدفعون ثمنه عبر التضخم، أو يُستبعدون تمامًا.",
  "pr-1-v": "×3.3",
  "pr-1": "تضاعفت الكتلة النقدية لليورو (M2) أكثر من ثلاث مرات منذ 2001: من أقل من 4.6 إلى نحو 15.1 تريليون يورو.",
  "pr-2": "من كل الثروة الشخصية في العالم يملكها أغنى 10 %. أما النصف الأفقر من البشرية فيملك نحو 2 %.",
