  "eco-label": "अर्थव्यवस्था",
  "eco-h2": "एक चक्र, तीन भूमिकाएँ",
  "eco-sub": "लोग बुनियादी आय पाते हैं और उसे खर्च करते हैं। व्यवसाय उसे कमाते हैं और वेतन व खरीद के रूप में आगे बढ़ाते हैं। जो पैसा रुका रहता है या नेटवर्क छोड़ता है, वह बुनियादी आय में लौटता है और वहाँ से सभी को बराबर मिलता है।",
