  "cmp-note": "ये नियम 26 सितंबर 2026 से लागू हैं। हर कटौती 100 % बुनियादी आय में जाती है।",
  "ppl-label": "लोगों के लिए",
  "ppl-h2": "हर व्यक्ति से छह वादे",
  "ppl-sub": "सबसे निष्पक्ष पैसा पहले उस व्यक्ति को निष्पक्ष लगना चाहिए जिसके पास कम है।",
  "ppl-1": "<strong>आपका उचित हिस्सा अछूता है।</strong> पहले 1,000 AEQ पर कभी कटौती नहीं होती।",
  "ppl-2": "<strong>रोज़मर्रा की ज़िंदगी में कोई खर्च नहीं।</strong> हर महीने खर्च किए गए पहले 1,000 AEQ शुल्क-मुक्त हैं।",
  "ppl-3": "<strong>वेतन वेतन है।</strong> हर महीने 3,000 AEQ तक बिना शुल्क यूरो या डॉलर में बदले जा सकते हैं, पैसा कहीं से भी आया हो।",
  "ppl-4": "<strong>बचत की अनुमति है।</strong> 5,000 AEQ तक आपकी बचत कुछ नहीं खोती।",
  "ppl-5": "<strong>जिसके पास ज़्यादा है, वह ज़्यादा योगदान देता है।</strong> 5,000 AEQ से ऊपर की बचत पर हर महीने 0.5 %; 25,000 AEQ की सीमा बनी रहती है।",
  "ppl-6": "<strong>रखने और निकालने के लिए लोग हमेशा व्यवसायों से कम चुकाते हैं,</strong> और कोई भी जो चुकाता है, वह सभी लोगों को बराबर लौटता है।",
  "biz-label": "व्यवसायों के लिए",
  "biz-h2": "AEQ स्वीकार करें, आगे बढ़ाएँ, कुछ न चुकाएँ",
  "biz-sub": "व्यवसाय AEQ स्वीकार कर सकते हैं, रख सकते हैं और खर्च कर सकते हैं। नियम पैसे को उनके ज़रिए लोगों तक वापस पहुँचाते हैं: पैसा रोककर रखने की कीमत है, आगे बढ़ाना मुफ़्त है।",
  "biz-b1-h": "कोई कार्ड शुल्क नहीं",
  "biz-b1-p": "भुगतान से व्यवसाय का कुछ खर्च नहीं होता। ग्राहक हर महीने पहले 1,000 AEQ बिना शुल्क खर्च करते हैं।",
  "biz-b2-h": "शुल्क-मुक्त वेतन",
  "biz-b2-p": "AEQ में दिया गया वेतन मुफ़्त है। हर व्यक्ति हर महीने 3,000 AEQ तक बिना शुल्क यूरो या डॉलर में बदल सकता है।",
  "biz-b3-h": "विकास की कोई सीमा नहीं",
  "biz-b3-p": "लोग अधिकतम 25,000 AEQ रख सकते हैं; व्यवसायों की कोई तय सीमा नहीं। डेढ़ महीने के कारोबार तक कभी कोई शुल्क नहीं।",
  "biz-b4-h": "सेकंडों में भुगतान",
  "biz-b4-p": "पैसा सेकंडों में पहुँचता है। कोई चार्जबैक नहीं, निपटान का इंतज़ार नहीं।",
  "biz-r1-k": "रुका हुआ पैसा",
  "biz-r1-v": "1.5 महीने के कारोबार तक (कम से कम 2,000 AEQ): मुफ़्त · 3 महीने के कारोबार तक: ऊपर वाले हिस्से पर हर महीने 0.5 % · उससे ऊपर: हर महीने 2 % · पहले छह महीने: कभी भी किसी व्यक्ति से ज़्यादा नहीं (25,000 AEQ तक)",
  "biz-r2-k": "कारोबार में क्या गिना जाता है",
  "biz-r2-v": "पिछले 90 दिनों का औसत, या पिछले 12 महीनों का, अगर वह ज़्यादा हो (मौसमी व्यवसायों के लिए)। ख़रीदारी प्रति व्यक्ति प्रति तिमाही 9,000 AEQ तक गिनी जाती है; व्यवसायों के बीच केवल अधिशेष गिना जाता है; वेतन, आपके अपने भुगतान और AEQ में विनिमय नहीं गिने जाते।",
  "biz-r3-k": "यूरो या डॉलर में निकासी",
  "biz-r3-v": "2 % शुल्क। जो आपने ख़ुद AEQ में बदला, वह बिना शुल्क वापस जाता है। लोग: इसके अलावा हर महीने 3,000 AEQ मुफ़्त",
  "biz-r4-k": "व्यवसायों के बीच",
  "biz-r4-v": "0.1 %",
  "biz-r5-k": "यह कहाँ जाता है",
  "biz-r5-v": "हर कटौती 100 % बुनियादी आय में जाती है, हर व्यक्ति को बराबर",
  "biz-live-from": "नियम लागू होंगे",
  "biz-live-count": "पंजीकृत व्यवसाय",
  "biz-link": "पूरी अवधारणा पढ़ें →",
