  "jn-1-h": "व्यावसायिक खाता खोलें",
  "jn-1-p": "एक सत्यापित व्यक्ति और व्यवसाय का वॉलेट साथ में हस्ताक्षर करते हैं। हर व्यवसाय में 10 तक ज़िम्मेदार लोग, हर व्यक्ति के अधिकतम 3 व्यवसाय। न कोई रजिस्ट्री, न कोई द्वारपाल।",
  "jn-3-h": "आगे बढ़ाएँ",
