function setLang(lang) {
  if (!T[lang]) return;
  const sel = document.getElementById('lang-sel');
  if (sel) sel.value = lang;
  document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
  document.documentElement.lang = lang;
  try { localStorage.setItem(LANG_KEY, lang); } catch (e) { /* private mode — lasts this page view only */ }
  const t = T[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    // Values may contain markup the layout depends on — the headline's <br>
    // and gradient <span>, the em dash in the social standfirst. None of it
    // is user-supplied; it all comes from the table above.
    if (t[key] !== undefined) el.innerHTML = t[key];
  });
  renderBizFrom();
}

// The live figures deliberately sit OUTSIDE every translated element (see the
// UBI line in landing.go): setLang() overwrites innerHTML, so a value written
// into a translated node would be wiped the moment someone switched language.
function initLang() {
  const sel = document.getElementById('lang-sel');
  if (sel) sel.addEventListener('change', function () { setLang(this.value); });
  let stored = null;
  try { stored = localStorage.getItem(LANG_KEY); } catch (e) { /* private mode */ }
  if (stored && T[stored]) { setLang(stored); return; }
  // Noch keine Wahl: die Sprache des Browsers, sofern es sie gibt. Ein Laie
  // aus Deutschland soll nicht zuerst eine englische Seite sehen. Nicht
  // gespeichert -- erst eine bewusste Wahl im Menue bleibt haften.
  const wuensche = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || '']);
  for (const w of wuensche) {
    const l = String(w).slice(0, 2).toLowerCase();
    if (T[l]) { if (l !== 'en') setLangOhneSpeichern(l); return; }
  }
}

// setLangOhneSpeichern: wie setLang, aber ohne die Wahl zu merken.
function setLangOhneSpeichern(lang) {
  let vorher = null;
  try { vorher = localStorage.getItem(LANG_KEY); } catch (e) { /* private mode */ }
  setLang(lang);
  try { if (vorher === null) localStorage.removeItem(LANG_KEY); } catch (e) { /* private mode */ }
}

const fmt = (n, d = 0) => n.toLocaleString(undefined, {minimumFractionDigits: d, maximumFractionDigits: d});

function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = value;
}

// The GHOSTDAG badge in the header reports whether this page can actually
// reach the node, not whether someone remembered to write "healthy" into the
// markup. loadStats already fetches /api/status every cycle, so the badge
// rides on a request that has to happen anyway: it goes red the moment that
// request stops coming back, which is the only state worth showing.
function setHealthBadge(ok, note) {
  const el = document.getElementById('health-badge');
  if (!el) return;
  el.classList.toggle('badge-health-healthy', ok);
  el.classList.toggle('badge-health-unhealthy', !ok);
  el.textContent = ok ? '● GHOSTDAG' : '● NO NODE';
  el.title = note;
}

async function loadStats() {
  try {
    const d = await fetch('/api/status').then(r => r.json());
    setHealthBadge(true, 'Node answering — height ' + (d.height !== undefined ? d.height.toLocaleString() : '?'));

    for (const p of ['stat', 'tw']) {
      if (d.total_humans !== undefined) setText(p + '-humans', d.total_humans.toLocaleString());
      if (d.total_supply) setText(p + '-supply', d.total_supply.replace(' AEQ', ''));
      if (d.height !== undefined) setText(p + '-blocks', d.height.toLocaleString());
    }

    if (typeof d.gini === 'number') {
      const g = d.gini.toFixed(4);
      setText('stat-gini', g);
      setText('tw-gini', g);
      // The static Bitcoin bar in landing.go is sized as gini*100%
      // (0.85 -> 85%). The live bar has to use the identical scale or the
      // comparison misrepresents Aequitas against the bar beside it.
      const pct = Math.min(d.gini * 100, 100);
      const barAeq = document.getElementById('bar-aeq');
      if (barAeq) barAeq.style.width = pct + '%';
      setText('val-aeq', g);
    }

    // UBI pool + countdown to the next distribution — the one live
    // mechanism figure this page still carries.
    if (typeof d.pool_ubi === 'string' || typeof d.pool_ubi === 'number') {
      setText('ubi-pool', fmt(parseFloat(d.pool_ubi), 4));
    }
    if (typeof d.ubi_next_payout_secs === 'number') {
      const s = Math.max(0, d.ubi_next_payout_secs);
      const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
      setText('ubi-next', h > 0 ? `${h}h ${m}m` : `${m}m`);
    }
  } catch (e) {
    // The one state the badge exists for: the page is up, the node is not.
    setHealthBadge(false, 'Cannot reach /api/status from this page');
  }
}

// Unternehmen (wirtschaft.go): ab wann die Regeln gelten und wie viele
// Unternehmen eingetragen sind -- ausserhalb jedes uebersetzten Elements,
// damit ein Sprachwechsel die Werte nicht loescht.
// Kept so setLang() can re-format the date in the newly chosen language.
var bizAktivAb = null;
function renderBizFrom() {
  renderCountdown();
  if (bizAktivAb === null) return;
  const lang = document.documentElement.lang || undefined;
  setText('biz-from', new Date(bizAktivAb * 1000).toLocaleDateString(lang, {day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC'}));
}

async function loadBusiness() {
  try {
    const d = await fetch('/api/unternehmen').then(r => r.json());
    if (typeof d.aktiv_ab === 'number') {
      bizAktivAb = d.aktiv_ab;
      renderBizFrom();
    }
    if (typeof d.anzahl === 'number') setText('biz-count', d.anzahl.toLocaleString());
  } catch (e) { /* bleibt ein Gedankenstrich */ }
}

// Countdown bis zum Start der Wirtschaftsregeln (Abschnitt "Aktuell").
// Standard ist der feste Termin; /api/unternehmen liefert ihn genau.
function renderCountdown() {
  const box = document.getElementById('cd-box');
  if (!box) return;
  const ab = (bizAktivAb ? bizAktivAb : 1790812800) * 1000;
  const tage = Math.ceil((ab - Date.now()) / 86400000);
  if (tage <= 0) { box.style.display = 'none'; return; }
  setText('cd-days', tage.toLocaleString());
}

// Abschnitte blenden beim Scrollen ein. Ohne IntersectionObserver, und
// spaetestens nach drei Sekunden, ist alles sichtbar -- die Seite darf nie
// leer bleiben.
function initReveal() {
  const els = document.querySelectorAll('.reveal');
  const alle = () => els.forEach(el => el.classList.add('in'));
  if (!('IntersectionObserver' in window)) { alle(); return; }
  const io = new IntersectionObserver(entries => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
  }, {rootMargin: '0px 0px -8% 0px'});
  els.forEach(el => io.observe(el));
  setTimeout(alle, 3000);
}

// Rechner Umlaufsicherung (Abschnitt "umlauf"): Menschen zahlen 0,5 % im
// Monat auf den Teil ueber 5.000 AEQ (wirtschaft.go, menschSparFreibetrag).
function initCalc() {
  const inp = document.getElementById('calc-in');
  if (!inp) return;
  const FREI = 5000, RATE = 0.005, MAX = +inp.max;
  const upd = () => {
    const b = +inp.value;
    const lang = document.documentElement.lang || undefined;
    setText('calc-bal', b.toLocaleString(lang));
    setText('calc-fee', (Math.max(0, b - FREI) * RATE).toLocaleString(lang, {maximumFractionDigits: 2}));
    const f = document.getElementById('calc-free'), o = document.getElementById('calc-over');
    if (f) f.style.width = (Math.min(b, FREI) / MAX * 100) + '%';
    if (o) o.style.width = (Math.max(0, b - FREI) / MAX * 100) + '%';
  };
  inp.addEventListener('input', upd);
  document.getElementById('lang-sel')?.addEventListener('change', upd);
  upd();
}

document.documentElement.classList.add('js');
initReveal();
initLang();
initCalc();
renderCountdown();
loadStats();
loadBusiness();
document.getElementById('lang-sel')?.addEventListener('change', loadBusiness);

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    e.preventDefault();
    document.querySelector(a.getAttribute('href'))?.scrollIntoView({behavior: 'smooth'});
  });
});
